package com.commercecore.cart;
import com.commercecore.promotion.PromotionDtos;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController@RequestMapping("/api/v1/cart")@SecurityRequirement(name="bearerAuth")public class CartController{private final CartService cart;public CartController(CartService c){cart=c;}
 @GetMapping CartDtos.CartResponse get(@AuthenticationPrincipal Jwt jwt){return cart.get(user(jwt));}@PostMapping("/items")ResponseEntity<CartDtos.CartResponse> add(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody CartDtos.AddItemRequest r){return ResponseEntity.status(201).body(cart.add(user(jwt),r));}
 @PutMapping("/items/{id}")CartDtos.CartResponse update(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid@RequestBody CartDtos.UpdateItemRequest r){return cart.update(user(jwt),id,r);}@DeleteMapping("/items/{id}")CartDtos.CartResponse remove(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return cart.remove(user(jwt),id);}@DeleteMapping CartDtos.CartResponse clear(@AuthenticationPrincipal Jwt jwt){return cart.clear(user(jwt));}
 @PostMapping("/promotion")CartDtos.CartResponse apply(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody PromotionDtos.CouponRequest r){return cart.applyPromotion(user(jwt),r.code());}@DeleteMapping("/promotion")CartDtos.CartResponse removePromotion(@AuthenticationPrincipal Jwt jwt){return cart.removePromotion(user(jwt));}
 private static UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}
}
